def bottom_k_by_value(d, k):
    if k <= 0 or not d:
        return []
    remaining = dict(d)
    result = []
    for _ in range(min(k, len(d))):
        best_key = None
        best_val = None
        for key, val in remaining.items():
            if best_key is None or (val, key) < (best_val, best_key):
                best_key, best_val = key, val
        result.append((best_key, best_val))
        del remaining[best_key]
    return result

def reduce_fraction(num, den):
    def gcd(a, b):
        return a if b == 0 else gcd(b, a % b)
    if den < 0:
        num, den = -num, -den
    g = gcd(abs(num), den)
    return (num // g, den // g)

