def smallest_multiple_up_to(n):
    from collections import defaultdict
    max_power = defaultdict(int)
    for i in range(2, n + 1):
        x = i
        p = 2
        while p * p <= x:
            count = 0
            while x % p == 0:
                x //= p
                count += 1
            max_power[p] = max(max_power[p], count)
            p += 1
        if x > 1:
            max_power[x] = max(max_power[x], 1)
    result = 1
    for p, power in max_power.items():
        result *= p ** power
    return result

def count_matching_digit_positions(a, b):
    sa, sb = str(a), str(b)
    length = max(len(sa), len(sb))
    sa = sa.rjust(length, '0')
    sb = sb.rjust(length, '0')
    matches = 0
    for i in range(length):
        if sa[i] == sb[i]:
            matches += 1
    return matches

def key_length_frequency(d):
    lengths = sorted(len(k) for k in d)
    freq = {}
    i = 0
    while i < len(lengths):
        j = i
        while j < len(lengths) and lengths[j] == lengths[i]:
            j += 1
        freq[lengths[i]] = j - i
        i = j
    return freq

