def sum_even_fibonacci_below(n):
    def fib_seq():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b
    total = 0
    for value in fib_seq():
        if value >= n:
            break
        if value % 2 == 0:
            total += value
    return total

