def count_prime_factors_with_multiplicity(n):
    def smallest_factor(x):
        if x % 2 == 0:
            return 2
        f = 3
        while f * f <= x:
            if x % f == 0:
                return f
            f += 2
        return x
    if n == 1:
        return 0
    factor = smallest_factor(n)
    return 1 + count_prime_factors_with_multiplicity(n // factor)

